require_once __DIR__.'/includes/functions.php';expire_donations($pdo);$search=trim($_GET['q']??'');$category=$_GET['category']??'';$sort=$_GET['sort']??'soonest';$allowedSort=['soonest'=>'expiry_at ASC','newest'=>'created_at DESC','name'=>'food_name ASC'];if(!isset($allowedSort[$sort]))$sort='soonest';$where="d.status IN ('Active','Partially Collected') AND d.remaining_quantity>0 AND d.expiry_at>NOW()";$params=[];if($search!==''){$where.=' AND (d.food_name LIKE ? OR d.locality LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}if(in_array($category,['Vegetarian','Non-Vegetarian','Vegan','Bakery','Fruits','Other'],true)){$where.=' AND d.category=?';$params[]=$category;} $stmt=$pdo->prepare("SELECT d.*,u.name donor_name FROM food_donations d JOIN users u ON u.id=d.donor_id WHERE $where ORDER BY ".$allowedSort[$sort]);$stmt->execute($params);$foods=$stmt->fetchAll();$page_title='Find available food | SharePlate';require __DIR__.'/includes/header.php';?>
<section class="page-hero compact"><div class="container"><p class="eyebrow">Good food, close by</p><h1>Find food to share</h1><p>Explore fresh surplus listings from donors in your community.</p></div></section><section class="container section"><form class="filter-bar" method="get"><label class="search-field"><span class="sr-only">Search by food or locality</span><input name="q" placeholder="Search food or locality" value="<?=e($search)?>"></label><label><span class="sr-only">Category</span><select name="category"><option value="">All categories</option><?php foreach(['Vegetarian','Non-Vegetarian','Vegan','Bakery','Fruits','Other'] as $c):?><option value="<?=e($c)?>" <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label><label><span class="sr-only">Sort listings</span><select name="sort"><option value="soonest" <?=$sort==='soonest'?'selected':''?>>Expiring soon</option><option value="newest" <?=$sort==='newest'?'selected':''?>>Newest first</option><option value="name" <?=$sort==='name'?'selected':''?>>Food name</option></select></label><button class="button">Search</button><?php if($search||$category):?><a class="button button-outline" href="available-food.php">Clear</a><?php endif;?></form>
<?php if($foods):?><div class="food-grid"><?php foreach($foods as $food):?><article class="food-card"><a class="food-image" href="food-details.php?id=<?=$food['id']?>"><img src="<?=e(image_url($food['image']))?>" alt="<?=e($food['food_name'])?>"></a><div class="food-card-body"><div class="card-topline"><span class="badge badge-category"><?=e($food['category'])?></span><span class="time-left" data-countdown="<?=e(date(DATE_ATOM,strtotime($food['expiry_at'])))?>"></span></div><h2><a href="food-details.php?id=<?=$food['id']?>"><?=e($food['food_name'])?></a></h2><p class="card-description"><?=e(mb_strimwidth($food['description'],0,100,'…'))?></p><div class="food-meta"><span>◉ <?=e($food['locality'])?></span><span>▣ <?=e(rtrim(rtrim(number_format((float)$food['remaining_quantity'],2,'.',''),'0'),'.'))?> <?=e($food['unit'])?></span></div><a class="button button-outline button-full" href="food-details.php?id=<?=$food['id']?>">View details</a></div></article><?php endforeach;?></div><?php else:?><div class="empty-state"><span class="empty-icon">♡</span><h2>No food listings found</h2><p>Try another search or check back soon—new food is shared every day.</p><a class="button" href="available-food.php">See all listings</a></div><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>